      "output": "```js\nfunction createCircuit(scene,track,samples){\nconst N=samples.length,PI=Math.PI,M=(c,o={})=>new THREE.MeshStandardMaterial({color:c,...o}),G=(o)=>new THREE.MeshPhysicalMaterial(o);\nconst cv=(w,h,f)=>{const c=document.createElement('canvas');c.width=w;c.height=h;f(c.getContext('2d'),w,h);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;t.anisotropy=8;return t};\nconst add=(g,m)=>{const o=new THREE.Mesh(g,m);scene.add(o);return o};\nconst last=samples[N-1].s+2;\nfunction rib(fa,fb,dy,vs){const p=[],u=[],ix=[];for(let i=0;i<=N;i++){const q=samples[i%N],s=i<N?q.s:last;for(const o of[fa(q),fb(q)])p.push(q.x+q.nx*o,q.y+Math.sin(q.bank)*o+dy,q.z+q.nz*o);u.push(0,s/vs,1,s/vs);if(i<N){const j=i*2;ix.push(j,j+2,j+1,j+1,j+2,j+3)}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(p,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(u,2));g.setIndex(ix);g.computeVertexNormals();return g}\nconst lane=cv(64,512,(x,w,h)=>{x.fillStyle='#000';x.fillRect(0,0,w,h);x.fillStyle='#777';x.fillRect(3,0,2,h);x.fillRect(59,0,2,h);x.fillRect(31,0,2,h/2)});\nadd(rib(q=>q.w,q=>-q.w,0,16),M('#0c0a16',{roughness:.35,metalness:.25,emissive:'#8a7cff',emissiveMap:lane,emissiveIntensity:.3,side:2}));\nconst kt=cv(8,64,(x,w,h)=>{x.fillStyle='#fff';x.fillRect(0,0,w,h);x.fillStyle='#555';x.fillRect(0,0,w,h/2)});\nconst km=[M('#200018',{emissive:'#ff2fd6',emissiveMap:kt,emissiveIntensity:2,side:2}),M('#001820',{emissive:'#00f0ff',emissiveMap:kt,emissiveIntensity:2,side:2})];\nadd(rib(q=>q.w+.7,q=>q.w,.04,4),km[0]);add(rib(q=>-q.w,q=>-q.w-.7,.04,4),km[1]);\nconst rot=q=>Math.atan2(q.tx,q.tz);\nconst grp=(q,a)=>{const g=new THREE.Group();g.position.set(q.x,q.y,q.z);g.rotation.y=a;scene.add(g);return g};\nconst q0=samples[0],sg=grp(q0,rot(q0)),W=q0.w;\nconst sl=new THREE.Mesh(new THREE.PlaneGeometry(2*W,2).rotateX(-PI/2).translate(0,.05,0),M('#1a1a22',{emissive:'#fff',emissiveIntensity:.6}));sg.add(sl);\nconst gb=[],gt=[],B=(a,b,c,x,y,z)=>new THREE.BoxGeometry(a,b,c).translate(x,y,z);\nfor(const s of[-1,1]){gb.push(B(.6,7,.6,s*(W+1.2),3.5,0));gt.push(B(.12,7,.12,s*(W+1.2)-s*.35,3.5,-.35))}\ngb.push(B(2*W+3,.8,.8,0,7,0));for(const y of[6.55,7.45])for(const z of[-.45,.45])gt.push(B(2*W+3,.1,.1,0,y,z));\nconst tubeM=M('#200018',{emissive:'#ff2fd6',emissiveIntensity:2});\nsg.add(new THREE.Mesh(mergeGeometries(gb),M('#111018',{metalness:.9,roughness:.3})),new THREE.Mesh(mergeGeometries(gt),tubeM));\nconst pts=track.points||[];\nconst near=p=>{const x=p[0]??p.x,z=p[1]??p.z;let b=0,d=1e18;samples.forEach((q,i)=>{const e=(q.x-x)**2+(q.z-z)**2;if(e<d){d=e;b=i}});return b};\nconst at=cv(256,128,(x,w,h)=>{x.fillStyle='#000';x.fillRect(0,0,w,h);x.strokeStyle='#fff';x.lineWidth=14;for(let i=0;i<3;i++){x.beginPath();x.moveTo(50+i*60,20);x.lineTo(95+i*60,64);x.lineTo(50+i*60,108);x.stroke()}x.strokeRect(4,4,w-8,h-8)});\nconst sm=M('#140a18',{emissive:'#ff8a3d',emissiveMap:at,emissiveIntensity:1.6,side:2}),pm=M('#111018',{metalness:.9,roughness:.3});\nfor(const s of track.signs||[]){const p=pts[s[0]];if(!p)continue;const q=samples[near(p)],sd=s[1],o=sd*(q.w+2.5);\nconst g=grp({x:q.x+q.nx*o,y:q.y+Math.sin(q.bank)*o,z:q.z+q.nz*o},rot(q)+PI);const b=new THREE.Mesh(new THREE.PlaneGeometry(4,2),sm);b.position.y=2.6;b.scale.x=sd>0?1:-1;g.add(b,new THREE.Mesh(B(.2,1.6,.2,0,.8,.1),pm))}\nconst ar=[[],[]],T=track.tunnel,am=[M('#200018',{emissive:'#ff2fd6',emissiveIntensity:2}),M('#001820',{emissive:'#00f0ff',emissiveIntensity:2})];\nif(T&&pts[T[0]]&&pts[T[1]]){const i0=near(pts[T[0]]),n=(near(pts[T[1]])-i0+N)%N,m=new THREE.Matrix4(),qq=new THREE.Quaternion(),e=new THREE.Euler(),one=new THREE.Vector3(1,1,1);\nfor(let k=0;k<=n;k+=4){const q=samples[(i0+k)%N];e.set(0,rot(q),0);qq.setFromEuler(e);m.compose(new THREE.Vector3(q.x,q.y,q.z),qq,one);ar[(k/4)%2].push(new THREE.TorusGeometry(q.w+1.6,.14,6,24,PI).applyMatrix4(m))}\nar.forEach((a,i)=>a.length&&add(mergeGeometries(a),am[i]))}\nlet gy=Infinity;for(const q of samples)gy=Math.min(gy,q.y);gy-=.15;\nconst gt2=cv(128,128,(x,w,h)=>{x.fillStyle='#000';x.fillRect(0,0,w,h);x.fillStyle='#fff';x.fillRect(0,0,w,3);x.fillRect(0,0,3,h)});gt2.repeat.set(150,150);\nadd(new THREE.PlaneGeometry(3000,3000).rotateX(-PI/2).translate(0,gy,0),M('#07050d',{roughness:.6,metalness:.3,emissive:'#ff2fd6',emissiveMap:gt2,emissiveIntensity:1.2}));\nconst wt=cv(64,64,(x,w,h)=>{x.fillStyle='#000';x.fillRect(0,0,w,h);for(let i=0;i<4;i++)for(let j=0;j<4;j++){const v=Math.random()<.6?40+Math.random()*160|0:10;x.fillStyle=`rgb(${v},${v},${v})`;x.fillRect(i*16+4,j*16+4,8,9)}});\nconst em=[];\nfor(const t of track.towers||[]){const[x,z,w,d,h,hu]=t,c=new THREE.Color().setHSL(hu>1?hu/360:hu,1,.55),tx=wt.clone();tx.needsUpdate=true;tx.repeat.set(Math.max(1,w/6),Math.max(1,h/6));\nadd(B(w,h,d,x,gy+h/2,z),G({color:'#05040a',metalness:.7,roughness:.15,emissive:c,emissiveMap:tx,emissiveIntensity:1.2}));\nconst e=[];for(const a of[-1,1])for(const b of[-1,1])e.push(B(.3,h,.3,x+a*w/2,gy+h/2,z+b*d/2));e.push(B(w,.3,.3,x,gy+h,z-d/2),B(w,.3,.3,x,gy+h,z+d/2),B(.3,.3,d,x-w/2,gy+h,z),B(.3,.3,d,x+w/2,gy+h,z));\nconst mm=M('#000',{emissive:c,emissiveIntensity:2});em.push(mm);add(mergeGeometries(e),mm)}\nfunction ring(r,fb,ft){const p=[],ix=[],S=160;for(let i=0;i<=S;i++){const a=i/S*2*PI,c=Math.cos(a)*r,s=Math.sin(a)*r;p.push(c,fb(i),s,c,ft(i),s);if(i<S){const j=i*2;ix.push(j,j+1,j+2,j+1,j+3,j+2)}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(p,3));g.setIndex(ix);g.computeVertexNormals();return g}\nconst mh=i=>gy+40+70*Math.abs(Math.sin(i*.37)*Math.cos(i*.13))+12*Math.abs(Math.sin(i*1.7));\nadd(ring(850,()=>gy,mh),M('#08040f',{roughness:.9,side:2}));\nconst rm=M('#000',{emissive:'#ff3cac',emissiveIntensity:2,side:2});add(ring(846,i=>mh(i)-1.4,i=>mh(i)+.2),rm);\nscene.fog=new THREE.FogExp2(0x1b1030,.0016);scene.background=new THREE.Color(0x1b1030);\nconst st=cv(4,256,(x,w,h)=>{const g=x.createLinearGradient(0,0,0,h);[[0,'#0a0418'],[.35,'#2a0d4f'],[.46,'#a0286e'],[.5,'#ff8a3d'],[.52,'#3a1450'],[1,'#1b1030']].forEach(s=>g.addColorStop(...s));x.fillStyle=g;x.fillRect(0,0,w,h)});\nconst dome=new THREE.Mesh(new THREE.SphereGeometry(950,32,16),M('#000',{emissive:'#fff',emissiveMap:st,side:1,fog:false,depthWrite:false}));dome.renderOrder=-2;\nconst sg2=cv(4,256,(x,w,h)=>{const g=x.createLinearGradient(0,0,0,h);g.addColorStop(0,'#ffe600');g.addColorStop(.5,'#ff8a3d');g.addColorStop(1,'#ff2fd6');x.fillStyle=g;x.fillRect(0,0,w,h)});\nconst sa=cv(4,128,(x,w,h)=>{x.fillStyle='#fff';x.fillRect(0,0,w,h);x.fillStyle='#000';for(let i=0;i<8;i++)x.fillRect(0,i*16,w,2+i)});sa.colorSpace=THREE.NoColorSpace;\nconst sunM=M('#000',{emissive:'#fff',emissiveMap:sg2,emissiveIntensity:3,alphaMap:sa,alphaTest:.5,fog:false,depthWrite:false});\nconst sun=new THREE.Mesh(new THREE.CircleGeometry(220,64),sunM);sun.position.set(0,gy+70,-900);sun.lookAt(0,gy+70,0);sun.renderOrder=-1;\nconst sky=new THREE.Scene();sky.add(dome,sun);scene.add(dome.clone(),sun.clone());\nreturn{sky,update(t){const p=Math.sin(t*2.2);km[0].emissiveIntensity=2+.25*p;km[1].emissiveIntensity=2-.25*p;am[0].emissiveIntensity=1.8+.3*Math.sin(t*3);am[1].emissiveIntensity=1.8+.3*Math.cos(t*3);tubeM.emissiveIntensity=1.9+.2*p;rm.emissiveIntensity=1.8+.2*Math.sin(t*.7);sa.offset.y=(t*.05)%1;for(const m of em)m.emissiveIntensity=1.9+.2*Math.sin(t+m.id)}}}\n```"
